import type { ConfigContext, ExpoConfig } from "expo/config";
// Plain JSON (generated by `pnpm tokens`) so this file loads in Node without a TS loader
// for workspace packages.
import palettes from "@scaffoldapp/tokens/palettes.json";

declare const process: { env: Record<string, string | undefined> };
declare const Buffer: { from(value: string, encoding: "base64"): { toString(encoding: "utf8"): string } };

const NAME = "Scaffold App";
const SCHEME = "scaffoldapp";
const BUNDLE_ID = "com.example.scaffoldapp";
/** Marketing version. Store build numbers are owned by EAS (eas.json: appVersionSource remote). */
const VERSION = "1.0.0";

type PaletteId = keyof typeof palettes.palettes;
const requested = (process.env.EXPO_PUBLIC_PALETTE ?? "").trim().toLowerCase();
const palette = palettes.palettes[(requested in palettes.palettes ? requested : palettes.default) as PaletteId];

/**
 * Clerk's Frontend API host, decoded from the publishable key (`pk_<env>_<base64 host$>`).
 * Passkeys need it as an iOS associated domain (`webcredentials:`); unset key = no domain.
 */
function clerkFrontendApi(key: string | undefined): string | null {
  const encoded = key?.split("_")[2];
  if (!encoded) return null;
  try {
    const host = Buffer.from(encoded, "base64").toString("utf8").replace(/\$$/, "");
    return /^[a-z0-9.-]+$/i.test(host) ? host : null;
  } catch {
    return null;
  }
}
const clerkHost = clerkFrontendApi(process.env.EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY);

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: NAME,
  slug: SCHEME,
  scheme: SCHEME,
  version: VERSION,
  platforms: ["ios", "android"],
  orientation: "portrait",
  userInterfaceStyle: "automatic",
  icon: "./assets/images/icon.png",
  ios: {
    bundleIdentifier: BUNDLE_ID,
    // iPhone only: an iPad build needs iPad screenshots and layouts reviewed at that size.
    supportsTablet: false,
    infoPlist: {
      ITSAppUsesNonExemptEncryption: false,
    },
    // Required-reason APIs used by React Native and Expo modules (add what ITMS-91053 emails list).
    privacyManifests: {
      NSPrivacyTracking: false,
      NSPrivacyTrackingDomains: [],
      NSPrivacyAccessedAPITypes: [
        { NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryUserDefaults", NSPrivacyAccessedAPITypeReasons: ["CA92.1"] },
        { NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryFileTimestamp", NSPrivacyAccessedAPITypeReasons: ["C617.1"] },
        { NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategorySystemBootTime", NSPrivacyAccessedAPITypeReasons: ["35F9.1"] },
        { NSPrivacyAccessedAPIType: "NSPrivacyAccessedAPICategoryDiskSpace", NSPrivacyAccessedAPITypeReasons: ["E174.1"] },
      ],
    },
    ...(clerkHost ? { associatedDomains: [`webcredentials:${clerkHost}`] } : {}),
  },
  android: {
    package: BUNDLE_ID,
    adaptiveIcon: {
      foregroundImage: "./assets/images/adaptive-icon.png",
      monochromeImage: "./assets/images/monochrome-icon.png",
      backgroundColor: palette.primary.light,
    },
    // The system photo picker needs no media permission; blocking these keeps the merged
    // manifest clean (Play's photo/video permissions declaration never triggers).
    blockedPermissions: [
      "android.permission.READ_MEDIA_IMAGES",
      "android.permission.READ_MEDIA_VIDEO",
      "android.permission.READ_MEDIA_AUDIO",
      "android.permission.READ_EXTERNAL_STORAGE",
      "android.permission.WRITE_EXTERNAL_STORAGE",
      "android.permission.RECORD_AUDIO",
      "android.permission.SYSTEM_ALERT_WINDOW",
    ],
    predictiveBackGestureEnabled: true,
  },
  plugins: [
    "expo-router",
    "expo-secure-store",
    "expo-font",
    [
      "expo-splash-screen",
      {
        image: "./assets/images/splash-icon.png",
        imageWidth: 200,
        resizeMode: "contain",
        backgroundColor: palette.splash.light,
        dark: { image: "./assets/images/splash-icon-dark.png", backgroundColor: palette.splash.dark },
      },
    ],
    [
      "expo-image-picker",
      {
        // Generic on purpose: every feature that takes photos (profile, chat, posts) shares them.
        photosPermission: `Allow ${NAME} to use your photos to add the ones you choose to share.`,
        cameraPermission: `Allow ${NAME} to use your camera to take photos you choose to share.`,
        microphonePermission: false,
      },
    ],
    // Feature config plugins are inserted just above the anchor: "./plugins/withPlaces", (files in mobile/plugins/).
    // scaffold:plugins
  ],
  experiments: { typedRoutes: true },
});
